        public enum McDeviceType
        {
            /// <summary>Data Register — word device, địa chỉ thập phân. Vd: D100</summary>
            D,
    
            /// <summary>Internal Relay — bit device, địa chỉ thập phân. Vd: M100</summary>
            M,
    
            /// <summary>
