        /// <summary>
        /// Xây dựng Mitsubishi MC Protocol 3E Binary request frame cho các lệnh đọc và ghi.
        ///
        /// Tài liệu tham chiếu: MELSEC Communication Protocol Reference Manual (SH-080008).
        ///
        /// Cấu trúc 3E Binary Request Header:
        ///   [0-1]  Subheader: 0x50 0x00
        ///   [2]    Network No (0x00 = local network)
        ///   [3]    PC No (0xFF = target CPU)
        ///   [4-5]  IO No: 0xFF 0x03 (0x03FF)
        ///   [6]    Station No: 0x00
        ///   [7-8]  Request Data Length (LE): số byte từ CPU timer đến hết frame
        ///   [9-10] CPU Monitoring Timer (LE): 0x0A 0x00 = 2500ms (hoặc tính theo timeoutMs)
        /// </summary>
        internal static class McFrameBuilder
        {
            // ─── Device Codes ────────────────────────────────────────────────────
            internal const byte DevD = 0xA8; // Word: Data Register
            internal const byte DevW = 0xB4; // Word: Link Register
            internal const byte DevM = 0x90; // Bit:  Internal Relay
            internal const byte DevX = 0x9C; // Bit:  Input Relay (Read only)
            internal const byte DevY = 0x9D; // Bit:  Output Relay
    
            internal static byte GetDeviceCode(McDeviceType device)
            {
                switch (device)
                {
                    case McDeviceType.D: return DevD;
                    case McDeviceType.W: return DevW;
                    case McDeviceType.M: return DevM;
                    case McDeviceType.X: return DevX;
                    case McDeviceType.Y: return DevY;
                    default: throw new ArgumentException($"Device không được hỗ trợ: {device}");
                }
            }
    
            // ─── Đọc dữ liệu (Command 0x0401) ────────────────────────────────────
    
            /// <summary>Tạo request đọc word device (D, W). Command 0x0401, Subcommand 0x0000.</summary>
            public static byte[] BuildWordReadRequest(
                byte networkNo, byte pcNo,
                McDeviceType device, int startAddress, ushort count, ushort cpuTimerUnits = 10)
            {
                if (device != McDeviceType.D && device != McDeviceType.W)
                    throw new ArgumentException($"Chỉ hỗ trợ đọc Word cho thiết bị D hoặc W, không hỗ trợ {device}.");
    
                return BuildBatchRead(networkNo, pcNo, device, startAddress, count, isWord: true, cpuTimerUnits: cpuTimerUnits);
            }
    
            /// <summary>Tạo request đọc bit device (M, X, Y). Command 0x0401, Subcommand 0x0001.</summary>
            public static byte[] BuildBitReadRequest(
                byte networkNo, byte pcNo,
                McDeviceType device, int startAddress, ushort count, ushort cpuTimerUnits = 10)
            {
                if (device != McDeviceType.M && device != McDeviceType.X && device != McDeviceType.Y)
                    throw new ArgumentException($"Chỉ hỗ trợ đọc Bit cho thiết bị M, X hoặc Y, không hỗ trợ {device}.");
    
                return BuildBatchRead(networkNo, pcNo, device, startAddress, count, isWord: false, cpuTimerUnits: cpuTimerUnits);
            }
    
            private static byte[] BuildBatchRead(
                byte networkNo, byte pcNo,
                McDeviceType device, int startAddress, ushort count, bool isWord, ushort cpuTimerUnits)
            {
                byte deviceCode = GetDeviceCode(device);
                const ushort reqDataLen = 12; // 2(timer) + 2(cmd) + 2(subcmd) + 3(addr) + 1(dev) + 2(points)
    
                byte[] f = new byte[21];
    
                // [0-1] Subheader
                f[0] = 0x50; f[1] = 0x00;
                // [2-3] Network No, PC No
                f[2] = networkNo;
                f[3] = pcNo;
                // [4-5] IO No = 0x03FF
                f[4] = 0xFF; f[5] = 0x03;
                // [6] Station No
                f[6] = 0x00;
                // [7-8] Request data length (LE)
                f[7] = (byte)(reqDataLen & 0xFF);
                f[8] = (byte)(reqDataLen >> 8);
                // [9-10] CPU monitoring timer (mỗi đơn vị = 250ms, mặc định 10 = 2500ms)
                f[9] = (byte)(cpuTimerUnits & 0xFF);
                f[10] = (byte)(cpuTimerUnits >> 8);
                // [11-12] Command = 0x0401 (Batch Read)
                f[11] = 0x01; f[12] = 0x04;
                // [13-14] Subcommand (word=0x0000, bit=0x0001)
                f[13] = isWord ? (byte)0x00 : (byte)0x01;
                f[14] = 0x00;
                // [15-17] Starting device address (LE, 3 bytes)
                f[15] = (byte)(startAddress & 0xFF);
                f[16] = (byte)((startAddress >> 8) & 0xFF);
                f[17] = (byte)((startAddress >> 16) & 0xFF);
                // [18] Device code
                f[18] = deviceCode;
                // [19-20] Number of points (LE)
                f[19] = (byte)(count & 0xFF);
                f[20] = (byte)(count >> 8);
    
                return f;
            }
    
            // ─── Ghi dữ liệu (Command 0x1401) ────────────────────────────────────
    
            /// <summary>
            /// Tạo request ghi Word device (D, W). Command 0x1401, Subcommand 0x0000.
            /// </summary>
            public static byte[] BuildWordWriteRequest(
                byte networkNo, byte pcNo,
                McDeviceType device, int startAddress, ushort[] values, ushort cpuTimerUnits = 10)
            {
                if (values == null || values.Length == 0 || values.Length > 960)
                    throw new ArgumentException("Số lượng word ghi phải từ 1 đến 960.", nameof(values));
    
                if (device != McDeviceType.D && device != McDeviceType.W)
                    throw new ArgumentException($"Chỉ cho phép ghi Word vào thiết bị D hoặc W (không hỗ trợ {device}).");
    
                ushort count = (ushort)values.Length;
                byte deviceCode = GetDeviceCode(device);
                int dataBytes = count * 2;
                ushort reqDataLen = (ushort)(12 + dataBytes);
    
                byte[] f = new byte[9 + reqDataLen];
    
                // Header 3E
                f[0] = 0x50; f[1] = 0x00;
                f[2] = networkNo;
                f[3] = pcNo;
                f[4] = 0xFF; f[5] = 0x03;
                f[6] = 0x00;
                f[7] = (byte)(reqDataLen & 0xFF);
                f[8] = (byte)(reqDataLen >> 8);
    
                // CPU Timer
                f[9] = (byte)(cpuTimerUnits & 0xFF);
                f[10] = (byte)(cpuTimerUnits >> 8);
    
                // Command = 0x1401 (Batch Write)
                f[11] = 0x01; f[12] = 0x14;
    
                // Subcommand = 0x0000 (Word)
                f[13] = 0x00; f[14] = 0x00;
    
                // Start Address (3 bytes LE)
                f[15] = (byte)(startAddress & 0xFF);
                f[16] = (byte)((startAddress >> 8) & 0xFF);
                f[17] = (byte)((startAddress >> 16) & 0xFF);
    
                // Device code
                f[18] = deviceCode;
    
                // Number of points (LE)
                f[19] = (byte)(count & 0xFF);
                f[20] = (byte)(count >> 8);
    
                // Write Data (Word LE)
                for (int i = 0; i < count; i++)
                {
                    int offset = 21 + (i * 2);
                    f[offset] = (byte)(values[i] & 0xFF);
                    f[offset + 1] = (byte)(values[i] >> 8);
                }
    
                return f;
            }
    
            /// <summary>
            /// Tạo request ghi Bit device (M, Y). Command 0x1401, Subcommand 0x0001.
            /// Chú ý an toàn: Từ chối thiết bị X (Input Relay là ngõ vào vật lý, không được ghi).
            /// </summary>
            public static byte[] BuildBitWriteRequest(
                byte networkNo, byte pcNo,
                McDeviceType device, int startAddress, bool[] values, ushort cpuTimerUnits = 10)
            {
                if (values == null || values.Length == 0 || values.Length > 1440)
                    throw new ArgumentException("Số lượng bit ghi phải từ 1 đến 1440.", nameof(values));
    
                if (device == McDeviceType.X)
                    throw new InvalidOperationException("Thiết bị X (Input Relay) là ngõ vào phần cứng của PLC, không được phép thực hiện thao tác ghi.");
    
                if (device != McDeviceType.M && device != McDeviceType.Y)
                    throw new ArgumentException($"Chỉ cho phép ghi Bit vào thiết bị M hoặc Y (không hỗ trợ {device}).");
    
                ushort count = (ushort)values.Length;
                byte deviceCode = GetDeviceCode(device);
                int dataBytes = (count + 1) / 2; // Mỗi byte chứa 2 nibble
                ushort reqDataLen = (ushort)(12 + dataBytes);
    
                byte[] f = new byte[9 + reqDataLen];
    
                // Header 3E
                f[0] = 0x50; f[1] = 0x00;
                f[2] = networkNo;
                f[3] = pcNo;
                f[4] = 0xFF; f[5] = 0x03;
                f[6] = 0x00;
                f[7] = (byte)(reqDataLen & 0xFF);
                f[8] = (byte)(reqDataLen >> 8);
    
                // CPU Timer
                f[9] = (byte)(cpuTimerUnits & 0xFF);
                f[10] = (byte)(cpuTimerUnits >> 8);
    
                // Command = 0x1401 (Batch Write)
                f[11] = 0x01; f[12] = 0x14;
    
                // Subcommand = 0x0001 (Bit)
                f[13] = 0x01; f[14] = 0x00;
    
                // Start Address (3 bytes LE)
                f[15] = (byte)(startAddress & 0xFF);
                f[16] = (byte)((startAddress >> 8) & 0xFF);
                f[17] = (byte)((startAddress >> 16) & 0xFF);
    
                // Device code
                f[18] = deviceCode;
    
                // Number of points (LE)
                f[19] = (byte)(count & 0xFF);
                f[20] = (byte)(count >> 8);
    
                // Write Data (Nibble packing: 2 points mỗi byte)
                byte[] packed = PackBitsToNibbles(values);
                Array.Copy(packed, 0, f, 21, packed.Length);
    
                return f;
            }
    
            /// <summary>
            /// Đóng gói các bit thành các byte theo định dạng nibble của MC Protocol (1 point = 1 nibble).
            /// Theo chuẩn MELSEC Communication Protocol Reference Manual (SH-080008):
            /// - Point chẵn (0, 2, 4...) đặt ở Upper Nibble (bits 4..7): 0x10 = ON, 0x00 = OFF.
            /// - Point lẻ (1, 3, 5...) đặt ở Lower Nibble (bits 0..3): 0x01 = ON, 0x00 = OFF.
            /// </summary>
            internal static byte[] PackBitsToNibbles(bool[] values)
            {
                int byteCount = (values.Length + 1) / 2;
                byte[] bytes = new byte[byteCount];
                for (int i = 0; i < values.Length; i++)
                {
                    if (values[i])
                    {
                        int byteIdx = i / 2;
                        if (i % 2 == 0)
                            bytes[byteIdx] |= 0x10; // First point in upper nibble (MSB)
                        else
                            bytes[byteIdx] |= 0x01; // Second point in lower nibble (LSB)
                    }
                }
                return bytes;
            }
        }
    
    // ===== Internal/McResponseParser.cs =====
    
        /// <summary>
        /// Phân tích và thẩm định nghiêm ngặt khung phản hồi 3E Binary từ PLC Mitsubishi.
        ///
        /// Cấu trúc 3E Binary Response:
        ///   [0-1]  Subheader: 0xD0 0x00
        ///   [2]    Network No (khớp với request)
        ///   [3]    PC No (khớp với request)
        ///   [4-5]  IO No
        ///   [6]    Station No
        ///   [7-8]  Response data length (LE) = số byte từ [9] trở đi (End code + Data)
        ///   [9-10] End code (LE): 0x0000 = Thành công
        ///   [11..] Data (Word hoặc Bit)
        /// </summary>
        internal static class McResponseParser
        {
            private const int FixedHeaderSize = 11; // Bytes 0–10
    
            // ─── Phân tích Đọc Word ──────────────────────────────────────────────
    
            /// <summary>
            /// Phân tích phản hồi đọc Word device.
            /// Thẩm định: Subheader, Network/PC No, Độ dài data, End Code, và số lượng word nhận được.
            /// </summary>
            public static McReadResult ParseWordResponse(
                byte[] response, byte expectedNetworkNo, byte expectedPcNo, ushort expectedCount,
                string reqHex = null, string respHex = null)
            {
                string err = ValidateHeader(response, expectedNetworkNo, expectedPcNo);
                if (err != null) return McReadResult.Fail(err, 0, reqHex, respHex);
    
                ushort endCode = ReadUInt16LE(response, 9);
                if (endCode != 0x0000)
                    return McReadResult.Fail(FormatEndCode(endCode), endCode, reqHex, respHex);
    
                ushort respDataLen = ReadUInt16LE(response, 7);
                int neededDataBytes = expectedCount * 2;
                int expectedRespDataLen = 2 + neededDataBytes;
    
                if (respDataLen != expectedRespDataLen)
                {
                    return McReadResult.Fail(
                        $"Độ dài dữ liệu phản hồi không khớp: khai báo {respDataLen} bytes, kỳ vọng {expectedRespDataLen} bytes cho {expectedCount} words.",
                        0, reqHex, respHex);
                }
    
                int actualDataBytes = response.Length - FixedHeaderSize;
                if (actualDataBytes != neededDataBytes)
                {
                    return McReadResult.Fail(
                        $"Dữ liệu Word thực tế bị sai lệch: cần {neededDataBytes} bytes, nhận {actualDataBytes} bytes.",
                        0, reqHex, respHex);
                }
    
                ushort[] words = new ushort[expectedCount];
                for (int i = 0; i < expectedCount; i++)
                {
                    words[i] = ReadUInt16LE(response, FixedHeaderSize + (i * 2));
                }
    
                return McReadResult.OkWord(words, reqHex, respHex);
            }
    
            // ─── Phân tích Đọc Bit ───────────────────────────────────────────────
    
            /// <summary>
            /// Phân tích phản hồi đọc Bit device (nibble unpacking: 1 point = 1 nibble).
            /// Theo chuẩn MELSEC Communication Protocol Reference Manual (SH-080008):
            /// - Point chẵn (0, 2, 4...) ở Upper Nibble (bits 4..7).
            /// - Point lẻ (1, 3, 5...) ở Lower Nibble (bits 0..3).
            /// </summary>
            public static McReadResult ParseBitResponse(
                byte[] response, byte expectedNetworkNo, byte expectedPcNo, ushort expectedCount,
                string reqHex = null, string respHex = null)
            {
                string err = ValidateHeader(response, expectedNetworkNo, expectedPcNo);
                if (err != null) return McReadResult.Fail(err, 0, reqHex, respHex);
    
                ushort endCode = ReadUInt16LE(response, 9);
                if (endCode != 0x0000)
                    return McReadResult.Fail(FormatEndCode(endCode), endCode, reqHex, respHex);
    
                ushort respDataLen = ReadUInt16LE(response, 7);
                int neededDataBytes = (expectedCount + 1) / 2;
                int expectedRespDataLen = 2 + neededDataBytes;
    
                if (respDataLen != expectedRespDataLen)
                {
                    return McReadResult.Fail(
                        $"Độ dài dữ liệu phản hồi không khớp: khai báo {respDataLen} bytes, kỳ vọng {expectedRespDataLen} bytes cho {expectedCount} bits.",
                        0, reqHex, respHex);
                }
    
                int actualDataBytes = response.Length - FixedHeaderSize;
                if (actualDataBytes != neededDataBytes)
                {
                    return McReadResult.Fail(
                        $"Dữ liệu Bit thực tế bị sai lệch: cần {neededDataBytes} bytes, nhận {actualDataBytes} bytes.",
                        0, reqHex, respHex);
                }
    
                bool[] bits = new bool[expectedCount];
                for (int i = 0; i < expectedCount; i++)
                {
                    int byteIdx = FixedHeaderSize + (i / 2);
                    byte byteVal = response[byteIdx];
                    // Point chẵn ở upper nibble (bits 4..7), point lẻ ở lower nibble (bits 0..3)
                    bool value = (i % 2 == 0)
                        ? ((byteVal >> 4) & 0x0F) != 0
                        : (byteVal & 0x0F) != 0;
                    bits[i] = value;
                }
    
                return McReadResult.OkBit(bits, reqHex, respHex);
            }
    
            // ─── Phân tích Ghi Dữ Liệu ───────────────────────────────────────────
    
            /// <summary>
            /// Phân tích phản hồi ghi (Batch Write) MC Protocol 3E Binary.
            /// Phản hồi thành công có đúng 11 bytes (Subheader, Routing, Length=2, EndCode=0x0000).
            /// </summary>
            public static McWriteResult ParseWriteResponse(
                byte[] response, byte expectedNetworkNo, byte expectedPcNo,
                string reqHex = null, string respHex = null)
            {
                string err = ValidateHeader(response, expectedNetworkNo, expectedPcNo);
                if (err != null) return McWriteResult.Fail(err, 0, false, reqHex, respHex);
    
                ushort endCode = ReadUInt16LE(response, 9);
                if (endCode != 0x0000)
                    return McWriteResult.Fail(FormatEndCode(endCode), endCode, false, reqHex, respHex);
    
                ushort respDataLen = ReadUInt16LE(response, 7);
                if (respDataLen != 2)
                {
                    return McWriteResult.Fail(
                        $"Độ dài dữ liệu phản hồi ghi không hợp lệ: khai báo {respDataLen} bytes, kỳ vọng 2 bytes (EndCode).",
                        0, false, reqHex, respHex);
                }
    
                if (response.Length != FixedHeaderSize)
                {
                    return McWriteResult.Fail(
                        $"Kích thước phản hồi ghi không hợp lệ: nhận được {response.Length} bytes, kỳ vọng {FixedHeaderSize} bytes.",
                        0, false, reqHex, respHex);
                }
    
                return McWriteResult.Ok(reqHex, respHex);
            }
    
            // ─── Thẩm Định Header Chung ──────────────────────────────────────────
    
            private static string ValidateHeader(byte[] response, byte expectedNetworkNo, byte expectedPcNo)
            {
                if (response == null || response.Length < FixedHeaderSize)
                {
                    return $"Phản hồi quá ngắn hoặc rỗng: {response?.Length ?? 0} bytes (cần tối thiểu {FixedHeaderSize} bytes).";
                }
    
                if (response[0] != 0xD0 || response[1] != 0x00)
                {
                    return $"Subheader 3E phản hồi không hợp lệ: 0x{response[0]:X2} 0x{response[1]:X2} (yêu cầu 0xD0 0x00).";
                }
    
                if (response[2] != expectedNetworkNo)
                {
                    return $"Network No không khớp: yêu cầu {expectedNetworkNo}, nhận được {response[2]}.";
                }
    
                if (response[3] != expectedPcNo)
                {
                    return $"PC No không khớp: yêu cầu {expectedPcNo}, nhận được {response[3]}.";
                }
    
                // [4-5] Destination module I/O No. trong chuẩn 3E request là 0x03FF. Phản hồi phải khớp 0xFF 0x03.
                ushort ioNo = ReadUInt16LE(response, 4);
                if (ioNo != 0x03FF)
                {
                    return $"Module I/O No không hợp lệ trong phản hồi 3E: 0x{ioNo:X4} (kỳ vọng 0x03FF).";
                }
    
                // [6] Destination module station No: mặc định 0x00 cho local CPU.
                if (response[6] != 0x00)
                {
                    return $"Station No không hợp lệ trong phản hồi 3E: 0x{response[6]:X2} (kỳ vọng 0x00).";
                }
    
                return null;
            }
    
            internal static ushort ReadUInt16LE(byte[] buf, int offset)
                => (ushort)(buf[offset] | (buf[offset + 1] << 8));
    
            internal static string FormatEndCode(ushort code)
            {
                string desc;
                switch (code)
                {
                    case 0x0055: desc = "Lỗi lệnh (command hoặc subcommand không hợp lệ)"; break;
                    case 0xC050: desc = "Lỗi cài đặt thông số giao tiếp Ethernet"; break;
                    case 0xC051: desc = "Số điểm ghi/đọc vượt quá giới hạn khung truyền"; break;
                    case 0xC056: desc = "Mã thiết bị (Device code) không tồn tại"; break;
                    case 0xC059: desc = "Không thể ghi dữ liệu vào thiết bị chỉ đọc"; break;
                    case 0xC05B: desc = "Địa chỉ thiết bị vượt quá phạm vi bộ nhớ PLC"; break;
                    case 0xC05C: desc = "Số lượng điểm đọc/ghi không hợp lệ"; break;
                    case 0x4031: desc = "Không có quyền truy cập bộ nhớ"; break;
                    default:     desc = "Xem bảng mã lỗi MELSEC Communication Protocol SH-080008"; break;
                }
                return $"PLC báo lỗi, End Code: 0x{code:X4} — {desc}";
            }
        }
    
    }
